function postCard(original){const p={...original};if(p.id==='a1'&&audience==='school'){p.body='Die A1 Fahrschule ergänzt unser Netzwerk in Herne. Lernen Sie unseren Kooperationspartner und sein Ausbildungsangebot kennen.';p.cta='Kooperation ansehen';}if(audience==='school'&&p.id==='emre'){p.title='So sieht Zusammenarbeit vor Ort aus.';p.body='Fahrschule Emre ist unser erster Kooperationspartner. Erfahren Sie mehr über die Zusammenarbeit und lernen Sie die Fahrschule kennen.';p.cta='Kooperation ansehen';}else if(audience==='learner'&&p.id==='emre'){p.title='Lerne Fahrschule Emre kennen.';p.body='Standorte, Führerscheinklassen und Ansprechpartner: Hier findest du die Infos zur Fahrschule Emre.';}if(p.id==='instagram')p.body=audience==='school'?'Unsere erste Fahrschulkooperation: die Ankündigung mit Fahrschule Emre auf Instagram.':'Fahrschule Emre kennenlernen: unsere gemeinsame Ankündigung auf Instagram.';return `<article class="post" data-post="${p.id}"><div class="post-top"><p class="post-meta">${p.meta}</p><span class="post-tag">${p.tag}</span></div>${p.art?p.art():''}<div class="post-copy"><h3>${p.title}</h3><p>${p.body}</p><div class="post-actions"><a class="primary" href="${p.external||url(p.href)}" ${p.external?'target="_blank" rel="noopener noreferrer"':''}><span class="action-label">${p.cta}</span>${icon(p.external?'external':'arrow')}</a><button class="save" data-save="${p.id}" aria-pressed="${saved.includes(p.id)}" aria-label="${saved.includes(p.id)?'Nicht mehr merken':'Beitrag merken'}: ${esc(original.title)}">${icon('bookmark')}</button></div></div></article>`}
function pageHead(title,lead,back='',share=''){return `${back}<section class="page-head${share?' has-share':''}">${share?shareButton(share,'on-navy').replace('data-ls-share=','data-ls-audience="'+audience+'" data-ls-share='):''}<svg class="hero-lanes" viewBox="0 0 240 400" preserveAspectRatio="none" aria-hidden="true" focusable="false"><path vector-effect="non-scaling-stroke" d="M24 0V400M216 0V400" stroke-dasharray="26 22"/><path class="lane-move" vector-effect="non-scaling-stroke" d="M168 400V250C168 190 72 200 72 140V0"/></svg><div class="hero-copy"><h1>${title}</h1><p>${lead}</p></div></section>`}
function intro(k,h,p){return `<div class="intro"><p class="eyebrow">${k}</p><h1>${h}</h1><p>${p}</p></div>`}
function updates(){const school=audience==='school';const items=[
 ...(!school?[['radar','25 Situationen aus Fahrerperspektive','Gefahrenradar jetzt in 3D','lernwelt/gefahrenradar/']]:[]),
 ['message','Antworten zu Angeboten & Kontakt','Frag LANE SWITCH','#assistent'],
 ...(school?[['compass','Informationen online & als PDF','Navigator-Demo','/navigator/demo'],['compass','Neu für Partnerfahrschulen','Navigator: Zugang & Anmeldung','/navigator/zugang']]:[['check','Deine Checkliste nach der Prüfung','Startklar-Check','#startklar'],['network','Infos online & als PDF','Navigator bei deiner Partnerfahrschule','kooperationen/fahrschulen/']]),
 ['tools','Förderung selbst berechnen','Förderrechner Altersvorsorge',school?'altersvorsorge/?zielgruppe=fahrschulen':'altersvorsorge/?zielgruppe=fahrschueler']
];return `<div class="section-row"><h2>Was gibt’s Neues?</h2><span class="post-meta">Wischen & entdecken</span></div><div class="updates" aria-label="Neuigkeiten">${items.map(([i,k,t,h])=>`<a class="update" href="${href(h)}"><span class="update-icon">${icon(i)}</span><span><small>${k}</small><strong>${t}</strong></span></a>`).join('')}</div>`}
