const contactDrafts={learner:{},school:{}};
const SK_QUESTIONS=[
{id:'car',q:'Womit fährst du nach der Prüfung?',o:[['parents','Mit dem Auto meiner Eltern'],['planned','Ein eigenes Auto ist geplant'],['own','Ich habe schon ein eigenes Auto'],['none','Vorerst fahre ich kaum']]},
{id:'bf17',q:'Fährst du begleitet ab 17?',o:[['yes','Ja, mit Begleitperson'],['no','Nein, ich fahre allein']]},
{id:'km',q:'Wie viel wirst du voraussichtlich fahren?',o:[['low','Eher selten, ab und zu am Wochenende'],['mid','Regelmäßig, zum Beispiel zur Arbeit oder Schule'],['high','Viel, auch längere Strecken']]},
{id:'park',q:'Wo steht das Auto meistens?',o:[['garage','In einer Garage oder auf einem Stellplatz'],['street','Auf der Straße'],['unknown','Weiß ich noch nicht']]},
{id:'focus',q:'Was ist dir am wichtigsten?',o:[['cost','Laufende Kosten im Griff behalten'],['damage','Auch bei Schäden am eigenen Auto abgesichert sein'],['help','Im Ernstfall wissen, was zu tun ist']]},
{id:'accident',q:'Weißt du, was nach einem Unfall zu tun ist?',o:[['yes','Ja, die Schritte kenne ich'],['some','Ungefähr'],['no','Nicht wirklich']]}];
const sk={answers:{},done:false};
function skItems(a){const L=[];const add=(t,d,link)=>L.push({t,d,link});
if(a.car==='parents'){add('Fahrerkreis im Vertrag der Eltern klären','Bei vielen Kfz-Verträgen müssen alle Fahrer:innen angegeben werden. Fehlt eine junge Fahrerin oder ein junger Fahrer, können Nachzahlungen fällig werden. Sprich das mit deinen Eltern an, bevor du losfährst.',['easi-drive/','EaSI Drive verstehen']);}
if(a.car==='planned'){add('Kosten vor dem Kauf durchrechnen','Versicherung, Kfz-Steuer, Kraftstoff, Wartung und Reifen kommen jeden Monat dazu. Rechne sie durch, bevor du dich für ein Modell entscheidest.',['fahrzeugkosten/','Fahrzeugkosten berechnen']);add('Versicherung vor der Unterschrift prüfen','Modell, Typklasse und Regionalklasse beeinflussen den Beitrag. Hol dir ein Angebot ein, bevor du den Kaufvertrag unterschreibst.',null);}
if(a.car==='own'){add('Vertragsdaten prüfen','Stimmen Fahrerkreis, jährliche Fahrleistung und Abstellort in deinem Vertrag? Falsche Angaben können später teuer werden.',null);}
if(a.bf17==='yes'){add('Begleitpersonen richtig eintragen','Beim begleiteten Fahren dürfen nur die Personen mitfahren, die in deiner Prüfungsbescheinigung eingetragen sind. Beziehe deine Eltern auch bei allen Vertragsfragen ein.',null);}
if(a.km&&a.car!=='none'){add('Fahrleistung realistisch angeben',a.km==='high'?'Du fährst viel: Gib die erwartete Kilometerzahl ehrlich an und prüfe sie nach dem ersten Jahr.':'Die jährliche Kilometerzahl beeinflusst den Beitrag. Schätze sie realistisch und prüfe sie nach dem ersten Jahr.',null);}
if(a.park==='street'||a.park==='unknown'){add('Abstellort korrekt angeben','Ob das Auto in der Garage oder auf der Straße steht, kann für den Beitrag eine Rolle spielen. Gib den üblichen Abstellort an.',null);}
if(a.focus==='damage'){add('Haftpflicht und Kasko unterscheiden','Die Kfz-Haftpflicht ist Pflicht und zahlt Schäden, die du anderen zufügst. Schäden am eigenen Auto deckt sie nicht. Dafür gibt es Teil- oder Vollkasko.',null);}
if(a.focus==='cost'){add('Laufende Kosten im Blick behalten','Ein monatliches Budget für alle Autokosten verhindert böse Überraschungen.',['fahrzeugkosten/','Fahrzeugkosten berechnen']);}
if(a.focus==='help'||a.accident!=='yes'){add('Unfallhelfer griffbereit haben','Der Unfallhelfer führt dich Schritt für Schritt durch die ersten Minuten nach einem Unfall. Lege ihn dir auf den Startbildschirm.',['unfallhelfer/','Unfallhelfer öffnen']);}
if(a.accident==='no'){add('Gefahren früh erkennen','Trainiere im Gefahrenradar, kritische Situationen früh zu sehen.',['lernwelt/gefahrenradar/','Gefahrenradar starten']);}
add('Probezeit ernst nehmen','In den ersten zwei Jahren gilt die Probezeit, und bis 21 gilt ein absolutes Alkoholverbot am Steuer. Schwere Verstöße führen zu einem Aufbauseminar und verlängern die Probezeit auf vier Jahre.',null);
return L;}
function skReport(){const a=sk.answers;const lines=['Mein Startklar-Check:'];SK_QUESTIONS.forEach(q=>{const o=q.o.find(x=>x[0]===a[q.id]);lines.push('- '+q.q+' '+(o?o[1]:'keine Angabe'));});return lines.join('\n');}
function renderStartklar(){const a=sk.answers;const all=SK_QUESTIONS.every(q=>a[q.id]);const head=pageHead('Startklar-Check','Führerschein bestanden? Sechs kurze Fragen, danach bekommst du deine persönliche Checkliste fürs erste Fahren.',`<a class="small-link back-link" href="#werkzeuge">← Zurück zu den Werkzeugen</a>`,'startklar');
if(sk.done&&all){const items=skItems(a);document.getElementById('view').innerHTML=head+`<section class="home-section" aria-labelledby="sk-result-title"><div class="home-head"><h2 id="sk-result-title" tabindex="-1">Deine Checkliste</h2><span class="search-count">${items.length} Punkte</span></div><ol class="sk-list">${items.map(i=>`<li class="sk-item"><span class="sk-check" aria-hidden="true">${icon('check')}</span><div><h3>${i.t}</h3><p>${i.d}</p>${i.link?`<a class="small-link" href="${url(i.link[0])}">${i.link[1]} ${icon('arrow')}</a>`:''}</div></li>`).join('')}</ol><p class="form-caption sk-note">Allgemeine Orientierung, keine Beratung im Einzelfall. Deine Antworten werden nicht gespeichert und nicht übertragen.</p></section><section class="home-section home-person" aria-labelledby="sk-person-title"><img class="portrait" src="${url('assets/steven-portrait.jpg?v=2')}" width="160" height="160" alt="Steven Dragojevic" loading="lazy" decoding="async"><div class="person-copy"><h2 id="sk-person-title">Ergebnis gemeinsam durchgehen?</h2><p>Steven schaut sich deine Checkliste mit dir an und beantwortet deine Fragen. Freiwillig und unverbindlich.${a.bf17==='yes'?' Gern auch zusammen mit deinen Eltern.':''}</p></div><button class="primary" type="button" id="sk-contact"><span class="action-label">Ergebnis besprechen</span>${icon('arrow')}</button></section><div class="sk-again"><button class="secondary" type="button" id="sk-restart">Check neu starten</button></div>`;document.getElementById('sk-result-title').focus({preventScroll:true});return;}
const n=SK_QUESTIONS.filter(q=>a[q.id]).length;
document.getElementById('view').innerHTML=head+`<form class="sk-form" id="sk-form" novalidate><div class="sk-progress"><span>${n} von ${SK_QUESTIONS.length} beantwortet</span><progress max="${SK_QUESTIONS.length}" value="${n}" aria-label="Beantwortete Fragen"></progress></div>${SK_QUESTIONS.map((q,i)=>`<fieldset class="sk-q"><legend><span class="sk-num">Frage ${i+1}</span>${q.q}</legend><div class="sk-options">${q.o.map(([v,t])=>`<label class="sk-option"><input type="radio" name="${q.id}" value="${v}" ${a[q.id]===v?'checked':''}><span>${t}</span></label>`).join('')}</div></fieldset>`).join('')}<p class="form-caption" id="sk-hint" role="status">${all?'':'Beantworte alle sechs Fragen, um deine Checkliste zu sehen.'}</p><button class="primary" type="submit"${all?'':' aria-disabled="true"'}><span class="action-label">Checkliste anzeigen</span>${icon('arrow')}</button></form>`;}
document.addEventListener('change',e=>{if(e.target.closest('#sk-form')&&e.target.name){sk.answers[e.target.name]=e.target.value;const n=SK_QUESTIONS.filter(q=>sk.answers[q.id]).length;const f=document.getElementById('sk-form');f.querySelector('.sk-progress span').textContent=`${n} von ${SK_QUESTIONS.length} beantwortet`;f.querySelector('progress').value=n;const all=n===SK_QUESTIONS.length;f.querySelector('button[type=submit]').toggleAttribute('aria-disabled',!all);document.getElementById('sk-hint').textContent=all?'':'Beantworte alle sechs Fragen, um deine Checkliste zu sehen.';}});
document.addEventListener('submit',e=>{if(e.target.id==='sk-form'){e.preventDefault();const miss=SK_QUESTIONS.find(q=>!sk.answers[q.id]);if(miss){const el=e.target.querySelector(`input[name=${miss.id}]`);el.focus();document.getElementById('sk-hint').textContent='Bitte beantworte noch: '+miss.q;return;}sk.done=true;renderStartklar();window.scrollTo({top:0,behavior:'instant'});}});
document.addEventListener('click',e=>{if(e.target.closest('#sk-restart')){sk.answers={};sk.done=false;renderStartklar();window.scrollTo({top:0,behavior:'instant'});}if(e.target.closest('#sk-contact')){contactDrafts.learner={...contactDrafts.learner,topic:'Unfallabsicherung und erstes Auto',message:'Ich möchte mein Ergebnis aus dem Startklar-Check besprechen.\n\n'+skReport()};location.hash='#kontakt';}});

if(new URLSearchParams(location.search).get('anliegen')==='fahrschul-check'){audience='school';storage.set('ls-audience-v2',audience);let report='';try{const item=JSON.parse(sessionStorage.getItem('ls-check-handoff-v1')||'null');sessionStorage.removeItem('ls-check-handoff-v1');if(item&&typeof item.report==='string'&&item.report.length<=16000&&Number.isFinite(item.created)&&Date.now()-item.created>=0&&Date.now()-item.created<1800000)report=item.report;}catch{}contactDrafts.school={topic:'Ergebnis des Fahrschul-Checks besprechen',message:'Ich möchte mein Ergebnis aus dem Fahrschul-Check gemeinsam einordnen.'+(report?'\n\n'+report:'')};}
const contactTopics={learner:['Allgemeine Frage','Unfallabsicherung und erstes Auto','EaSI Drive','Fahrzeugkosten','Lernwelt und Gefahrenradar'],school:['20-Minuten-Kennenlernen','Versicherungscheck für die Fahrschule','Ergebnis des Fahrschul-Checks besprechen','Theoriebeitrag und Quiz','Tippgeberkooperation','Netzwerk und ergänzende Lösungen']};
function renderContact(){const school=audience==='school',draft=contactDrafts[audience];const field=(name)=>esc(draft[name]||'');document.getElementById('view').innerHTML=pageHead('Kontakt',school?'Ihre Anfrage zu Betrieb, Unterricht oder Zusammenarbeit. Persönlich und unverbindlich.':'Deine Frage zum ersten Auto, zur Absicherung oder zu unseren Lernangeboten.')+`<section class="contact-person" aria-label="Ansprechpartner"><img class="portrait" src="${url('assets/steven-portrait.jpg?v=2')}" width="160" height="160" alt="Steven Dragojevic" loading="lazy" decoding="async"><div class="contact-person-copy"><h2>Steven Dragojevic</h2><p>${school?'Ihr Ansprechpartner':'Dein Ansprechpartner'} bei LANE SWITCH</p><div class="contact-links"><a href="tel:+491727937262">${icon('phone')}0172 7937262</a><a href="mailto:kontakt@laneswitch.de">${icon('mail')}kontakt@laneswitch.de</a></div></div></section><h2 class="form-title">${school?'Anfrage vorbereiten':'Anfrage vorbereiten'}</h2><form class="inquiry-form" id="inquiry-form"><div class="form-grid"><label><span>Name *</span><input name="name" autocomplete="name" required value="${field('name')}"></label><label><span>E-Mail-Adresse</span><input name="email" type="email" autocomplete="email" value="${field('email')}"></label></div>${school?`<label><span>Fahrschule oder Unternehmen</span><input name="school" autocomplete="organization" value="${field('school')}"></label>`:''}<label><span>Telefonnummer <small>(optional)</small></span><input name="phone" type="tel" autocomplete="tel" value="${field('phone')}"></label><label><span>${school?'Ihr Anliegen':'Dein Anliegen'}</span><select name="topic">${contactTopics[audience].map(t=>`<option ${draft.topic===t?'selected':''}>${t}</option>`).join('')}</select></label><label><span>Nachricht</span><textarea name="message" rows="4" placeholder="${school?'Wobei können wir Sie unterstützen?':'Wobei können wir dir helfen?'}">${field('message')}</textarea></label>${school?`<label class="form-consent form-coop"><input name="coop" type="checkbox" ${draft.coop?'checked':''}><span><strong>Zusätzlich Kooperation anfragen</strong> (Login / Registrierung für den Fahrschul-Navigator). Name, Fahrschule, E-Mail und Telefon werden dafür direkt an LANE SWITCH übermittelt. Bei Interesse erhalten Sie einen persönlichen Einladungslink.</span></label>`:''}<label class="form-consent"><input name="consent" type="checkbox" required ${draft.consent?'checked':''}><span>Ich habe die <a href="${url('datenschutz/')}" target="_blank" rel="noopener">Datenschutzhinweise</a> gelesen. Bitte keine Gesundheits-, Vertrags- oder Bankdaten eintragen.</span></label><button class="primary" type="submit"><span class="action-label">E-Mail-Programm öffnen</span>${icon('arrow')}</button><p class="form-caption">${school?'Öffnet Ihr E-Mail-Programm mit der ausgefüllten Anfrage. Dort prüfen Sie die Nachricht und senden sie selbst ab.':'Öffnet dein E-Mail-Programm mit der ausgefüllten Anfrage. Dort prüfst du die Nachricht und sendest sie selbst ab.'}</p><p class="form-caption">Kein automatischer Versand. ${school?'Ihre':'Deine'} Formulareingaben bleiben bis zum Öffnen des E-Mail-Programms in dieser Browserseite und werden nicht dauerhaft gespeichert.</p></form><p class="legal-note">Steven Dragojevic ist angestellter Mitarbeiter im Versicherungsvertrieb der SIGNAL IDUNA Allgemeine Versicherung Aktiengesellschaft. Versicherungsberatung und Vermittlung erfolgen im Rahmen dieser Tätigkeit. Es findet kein unabhängiger Marktvergleich statt. Kontakt und Abschluss sind freiwillig. <a href="https://signal-iduna-agentur.de/steven.dragojevic/" target="_blank" rel="noopener noreferrer">Erstinformation und Vermittlerangaben ↗</a></p>`;}
function inquiryMessage(data,group){
 const value=k=>String(data.get(k)||'').trim();
 const role=group==='school'?'Fahrschule / Fahrlehrer:in':'Fahrschüler:in';
 const topic=value('topic').replace(/[\r\n]+/g,' ');
 const subject='LANE SWITCH – '+topic;
 const lines=['Rolle: '+role,'Name: '+value('name'),'E-Mail: '+value('email'),'Telefon: '+value('phone')];
 if(group==='school')lines.push('Fahrschule: '+value('school'));
 lines.push('Anliegen: '+topic,'','Nachricht:',value('message'));
 const body=lines.join('\r\n');
 return {subject,body,copy:'An: kontakt@laneswitch.de\nBetreff: '+subject+'\n\n'+body,href:'mailto:kontakt@laneswitch.de?subject='+encodeURIComponent(subject)+'&body='+encodeURIComponent(body)};
}
function showInquiry(form){
 const name=form.elements.namedItem('name');
 name.setCustomValidity(name.value.trim()?'':'Bitte gib deinen Namen ein.');
 // Kooperationsanfrage braucht Fahrschule und E-Mail (gleiche Prüfung wie auf /navigator/zugang).
 const coop=audience==='school'&&form.elements.namedItem('coop')?.checked;
 const schoolField=form.elements.namedItem('school'),mailField=form.elements.namedItem('email');
 if(schoolField){schoolField.required=!!coop;schoolField.setCustomValidity(coop&&schoolField.value.trim().length<3?'Bitte den Namen der Fahrschule angeben.':'');}
 if(mailField)mailField.required=!!coop;
 if(!form.reportValidity())return;
 if(coop){sendCooperation(new FormData(form)).finally(()=>openInquiryMail(form));return;}
 openInquiryMail(form);
}
function openInquiryMail(form){
 const message=inquiryMessage(new FormData(form),audience);
 document.getElementById('inquiry-handoff')?.remove();
 const panel=document.createElement('section');
 panel.id='inquiry-handoff';panel.className='contact-card';panel.style.marginTop='20px';
 panel.innerHTML='<h2>Anfrage im E-Mail-Programm senden</h2><p tabindex="-1" role="status" id="inquiry-status">Die Anfrage ist noch nicht gesendet. Prüfe sie in deinem E-Mail-Programm und sende sie dort ab. Falls sich kein Programm öffnet, kopiere den Text in eine E-Mail an kontakt@laneswitch.de.</p><label for="inquiry-copy-text">Deine vorbereitete E-Mail</label><textarea id="inquiry-copy-text" readonly rows="10" style="width:100%;max-width:100%;box-sizing:border-box;margin:12px 0;padding:12px;border:1px solid var(--line,#b8cbd4);border-radius:12px;background:var(--card,#fff);color:var(--ink,#092d46);font:inherit"></textarea><div class="post-actions"><a class="secondary" id="inquiry-open">E-Mail erneut öffnen</a><button class="secondary" type="button" id="inquiry-copy">Anfrage kopieren</button></div>';
 const text=panel.querySelector('textarea');text.value=message.copy;
 panel.querySelector('#inquiry-open').href=message.href;
 panel.querySelector('#inquiry-copy').onclick=async()=>{
  try{await navigator.clipboard.writeText(message.copy);panel.querySelector('#inquiry-status').textContent='Anfrage kopiert. Füge sie in eine E-Mail an kontakt@laneswitch.de ein und sende sie dort ab.';}
  catch{text.focus();text.select();panel.querySelector('#inquiry-status').textContent='Bitte den markierten Text kopieren und in deine E-Mail einfügen.';}
 };
 form.after(panel);panel.querySelector('#inquiry-status').focus({preventScroll:true});
 try{window.location.href=message.href;}catch{panel.querySelector('#inquiry-status').textContent='Das E-Mail-Programm konnte nicht geöffnet werden. Kopiere die Anfrage und sende sie an kontakt@laneswitch.de.';}
}
async function sendCooperation(data){
 const status=()=>document.getElementById('coop-status');
 const show=(text,ok)=>{let el=status();if(!el){el=document.createElement('p');el.id='coop-status';el.setAttribute('role','status');const host=document.getElementById('inquiry-handoff')||document.getElementById('inquiry-form');host.after(el);}el.className='coop-status'+(ok?' is-ok':' is-error');el.innerHTML=text;};
 const phone=String(data.get('phone')||'').trim();
 const body={action:'requestCooperation',school:String(data.get('school')||'').trim(),contact:String(data.get('name')||'').trim(),email:String(data.get('email')||'').trim(),phone:/^[+0-9 ()/-]{5,40}$/.test(phone)?phone:'',city:'',message:[String(data.get('topic')||''),String(data.get('message')||'').trim()].filter(Boolean).join(': ').slice(0,1500),consent:true};
 show('Kooperationsanfrage wird übermittelt …',true);
 try{const r=await fetch('/api/navigator',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const j=await r.json().catch(()=>({}));if(!r.ok)throw new Error(j.error||'');
  show('<strong>Kooperationsanfrage übermittelt.</strong> Steven meldet sich persönlich. Passt es, erhalten Sie einen Einladungslink für Ihren Zugang.',true);}
 catch(e){show(`Die Kooperationsanfrage konnte nicht übermittelt werden${e.message?' ('+esc(e.message)+')':''}. Sie können sie auch direkt <a href="/navigator/zugang#anfrage">auf der Anmeldeseite</a> stellen.`,false);}
}
function recommendationData(target){
 const title='LANE SWITCH';
 const url='https://laneswitch.online/?zielgruppe='+(target==='school'?'school':'learner');
 const description=target==='school'?'Ich möchte Ihnen LANE SWITCH empfehlen: ein Partnerkonzept mit Versicherungscheck, Theoriebeitrag und praktischen Arbeitshilfen für Fahrschulen.':'Schau dir LANE SWITCH an: Gefahrenradar, Lernwelt und Fahrzeugkosten-Rechner für deinen Start in die eigene Mobilität.';
 const text=description+'\n\n'+url;
 return {title,url,text,email:'mailto:?subject='+encodeURIComponent('Empfehlung: '+title)+'&body='+encodeURIComponent(text),whatsapp:'https://wa.me/?text='+encodeURIComponent(text)};
}
function openRecommend(){
 let target=audience;
 document.getElementById('recommend-app')?.remove();
 const d=document.createElement('dialog');d.id='recommend-app';d.setAttribute('aria-labelledby','recommend-title');
 d.innerHTML='<div class="dialog-head"><h2 id="recommend-title">LANE SWITCH empfehlen</h2><button class="icon-button" id="recommend-close" aria-label="Empfehlung schließen">×</button></div><div class="dialog-body"><p>Für wen ist deine Empfehlung?</p><div class="audience recommend-targets" role="group" aria-label="Zielgruppe der Empfehlung"><button data-recommend-target="learner">Fahrschüler:innen</button><button data-recommend-target="school">Fahrschulen</button></div><p id="share-preview" class="share-preview" style="white-space:pre-wrap;overflow-wrap:anywhere"></p><div class="share-actions"><button class="primary" id="share-native">Teilen</button><a class="secondary" id="share-email">Per E-Mail</a><a class="secondary" id="share-whatsapp" target="_blank" rel="noopener noreferrer">WhatsApp</a><button class="secondary" id="share-copy">Text & Link kopieren</button></div><p id="share-status" class="form-caption" role="status"></p><p class="form-caption">Für Outlook oder andere Mailprogramme nutze „Per E-Mail“. Falls eine App den Inhalt nicht übernimmt, kannst du Text und Link kopieren und dort einfügen. Du sendest die Empfehlung selbst in der gewählten App.</p></div>';
 const status=d.querySelector('#share-status');
 const copy=async()=>{
  const data=recommendationData(target);
  try{await navigator.clipboard.writeText(data.text);status.textContent='Text und Link kopiert. Du kannst beides in deiner Nachricht einfügen.';}
  catch{status.textContent='Kopieren war nicht möglich. Bitte den oben angezeigten Text samt Link markieren und kopieren.';}
 };
 const update=()=>{
  const data=recommendationData(target);
  d.querySelector('#share-preview').textContent=data.text;
  d.querySelector('#share-email').href=data.email;
  d.querySelector('#share-whatsapp').href=data.whatsapp;
  d.querySelectorAll('[data-recommend-target]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.recommendTarget===target)));
  status.textContent='';
 };
 d.querySelectorAll('[data-recommend-target]').forEach(b=>b.onclick=()=>{target=b.dataset.recommendTarget;update()});
 d.querySelector('#recommend-close').onclick=()=>d.close();
 d.querySelector('#share-copy').onclick=copy;
 d.querySelector('#share-native').onclick=async()=>{
  const data=recommendationData(target);
  if(!navigator.share){await copy();return;}
  try{
   // Keep the URL inside the text so receiving apps need not combine two fields.
   await navigator.share({title:data.title,text:data.text});
  }catch(e){
   if(e.name!=='AbortError')status.textContent='Teilen war nicht möglich. Nutze „Per E-Mail“, WhatsApp oder „Text & Link kopieren“.';
  }
 };
 d.addEventListener('close',()=>d.remove());document.body.append(d);update();d.showModal();
}
function renderRail(){const list=tools.filter(t=>t.group===audience&&!['konzept','start','navigator','navigator-demo'].includes(t.id)).slice(0,3);document.getElementById('rail').innerHTML=`<section class="rail-card"><p class="eyebrow">Deine Abkürzung</p><h2>Direkt zum Ziel</h2>${list.map(t=>`<a class="tool-short" href="${href(t.href)}">${icon(t.icon)}<span><strong>${t.title}</strong><small>${t.label}</small></span></a>`).join('')}<a class="small-link" href="#werkzeuge">Alle Werkzeuge ${icon('arrow')}</a></section><section class="rail-card rail-help"><h2>${audience==='school'?'Was bewegt Ihren Betrieb?':'Noch eine Frage offen?'}</h2><p>${audience==='school'?'Gemeinsam schauen, welche Unterstützung zu Ihrer Fahrschule passt.':'Von der Fahrschule zum ersten Auto. Steven hilft dir beim nächsten Schritt.'}</p>${action('#kontakt','Kontakt aufnehmen','primary accent')}</section><section class="rail-card"><h2>Einfach umschalten.</h2><p class="subtle">Fahrschule oder Fahrschüler:in? Oben kannst du jederzeit die Perspektive wechseln.</p></section>`;}
function renderAssistant(){mountAssistant(document.getElementById('view'),audience);}
function render(){document.getElementById('view').className='';const shortcut=document.getElementById('audience-shortcut');if(shortcut){shortcut.href=url(audience==='school'?'notfallcenter/':'unfallhelfer/');shortcut.innerHTML=icon('shield')+(audience==='school'?'Notfallcenter':'Unfallhelfer');}document.querySelectorAll('[data-audience]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.audience===audience)));document.querySelectorAll('[data-navigation]').forEach(n=>n.innerHTML=navigation(view==='news'||view==='startklar'?'werkzeuge':view));({entdecken:renderFeed,werkzeuge:renderTools,news:renderNewsView,startklar:renderStartklar,netzwerk:renderNetwork,assistent:renderAssistant,kontakt:renderContact}[view]||renderFeed)();renderRail();document.title='LANE SWITCH · '+(view==='news'?'Newsticker':view==='startklar'?'Startklar-Check':nav.find(n=>n[0]===view)?.[2]||'Entdecken');}
function route(){const id=location.hash.slice(1)||(location.pathname.includes('/kontakt/')?'kontakt':'');view=(id==='news'||id==='startklar'||nav.some(n=>n[0]===id))?id:'entdecken';if(view==='startklar'&&audience!=='learner'){audience='learner';storage.set('ls-audience-v2',audience);}render();window.scrollTo({top:0,behavior:'instant'});if(id==='empfehlen')openRecommend();}
function toast(text){clearTimeout(toastTimer);const el=document.getElementById('toast');el.textContent=text;el.hidden=false;toastTimer=setTimeout(()=>el.hidden=true,3500)}
function choose(value){audience=value;storage.set('ls-audience-v2',audience);filter='all';query='';render();}
function theme(){const dark=document.documentElement.dataset.theme==='dark';const b=document.getElementById('theme');b.innerHTML=icon(dark?'sun':'moon');b.setAttribute('aria-label',dark?'Hellen Modus aktivieren':'Dunklen Modus aktivieren');b.setAttribute('aria-pressed',String(dark));}
document.documentElement.dataset.theme=storage.get('laneswitch-theme-v1')==='dark'?'dark':'light';theme();
document.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));
document.getElementById('theme').addEventListener('click',()=>{document.documentElement.dataset.theme=document.documentElement.dataset.theme==='dark'?'light':'dark';storage.set('laneswitch-theme-v1',document.documentElement.dataset.theme);theme()});
document.addEventListener('click',e=>{if(e.target.closest('[data-recommend]')){openRecommend();return}const audienceButton=e.target.closest('[data-audience]');if(audienceButton){choose(audienceButton.dataset.audience);toast(audience==='school'?'Ansicht für Fahrlehrer:innen und Fahrschulen':'Ansicht für Fahrschüler:innen');return}const f=e.target.closest('[data-filter]');if(f){filter=f.dataset.filter;renderFeed();document.querySelector(`[data-filter="${filter}"]`)?.focus({preventScroll:true});return}const s=e.target.closest('[data-save]');if(s){const id=s.dataset.save;saved=saved.includes(id)?saved.filter(x=>x!==id):[...saved,id];const persisted=storage.set('ls-saved-v2',JSON.stringify(saved));s.setAttribute('aria-pressed',String(saved.includes(id)));s.setAttribute('aria-label',(saved.includes(id)?'Nicht mehr merken':'Beitrag merken')+': '+posts.find(p=>p.id===id).title);toast(saved.includes(id)?(persisted?'Auf diesem Gerät gemerkt':'Für diese Sitzung gemerkt'):'Aus deiner Merkliste entfernt');if(filter==='saved')renderFeed();return}});
document.addEventListener('input',e=>{if(e.target.id==='tool-search'){query=e.target.value;toolCards()}if(e.target.closest('#inquiry-form')&&(e.target.name==='name'||e.target.name==='school'))e.target.setCustomValidity('');if(e.target.closest('#inquiry-form')&&e.target.name==='coop'&&!e.target.checked){const f=e.target.form.elements;f.namedItem('school')?.setCustomValidity('');if(f.namedItem('school'))f.namedItem('school').required=false;if(f.namedItem('email'))f.namedItem('email').required=false;}if(e.target.closest('#inquiry-form')&&e.target.name)contactDrafts[audience][e.target.name]=e.target.type==='checkbox'?e.target.checked:e.target.value;});
document.addEventListener('submit',e=>{if(e.target.id==='inquiry-form'){e.preventDefault();showInquiry(e.target)}});
window.addEventListener('hashchange',route);route();
// First-visit choice, with a permanent switch in the main interface.
if(!prior&&!location.pathname.includes('/kontakt/')&&!location.hash&&!location.pathname.includes('/fahrschulen/')&&!location.pathname.includes('/fahrschueler/')){const welcome=document.createElement('dialog');welcome.id='welcome';welcome.setAttribute('aria-labelledby','welcome-title');welcome.innerHTML=`<div class="welcome"><img src="${url('assets/logo-primary.svg')}" class="logo-light" alt="LANE SWITCH" width="180"><img src="${url('assets/logo-primary-dark.svg')}" class="logo-dark" alt="LANE SWITCH" width="180"><p class="eyebrow">Schön, dass du da bist</p><h1 id="welcome-title">Was bringt dich<br>zu uns?</h1><p>Wähle deinen Einstieg. Du kannst die Ansicht jederzeit wechseln.</p><button class="welcome-choice" data-choice="learner"><span class="update-icon">${icon('car')}</span><span><strong>Ich mache den Führerschein</strong><small>Wissen, erstes Auto & sicher unterwegs</small></span>${icon('arrow')}</button><button class="welcome-choice" data-choice="school"><span class="update-icon">${icon('network')}</span><span><strong>Ich bin Fahrlehrer:in oder<br>betreibe eine Fahrschule</strong><small>Betrieb, Unterricht & Zusammenarbeit</small></span>${icon('arrow')}</button><button class="welcome-skip" id="welcome-skip">Erst einmal umsehen</button><p class="welcome-note">Deine Auswahl wird nur auf diesem Gerät gespeichert.</p></div>`;document.body.append(welcome);welcome.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{choose(b.dataset.choice);welcome.close();welcome.remove();document.querySelector(`[data-audience="${audience}"]`).focus({preventScroll:true});});welcome.querySelector('#welcome-skip').onclick=()=>{welcome.close();welcome.remove()};welcome.showModal();}

